package hu.synostream.android;
import org.json.*;import org.junit.*;import java.util.*;import static org.junit.Assert.*;
public class LibraryConfigTest {
    @Test public void oldDuplicateDefaultNamesConsolidateAllSources() throws Exception {JSONArray all=LibraryConfig.migrate(new JSONArray().put(library("a","Filmek",true,"/one")).put(library("b","filmek",true,"/two")));assertEquals(2,all.length());assertEquals(List.of("/one","/two"),LibraryConfig.paths(LibraryConfig.defaultLibrary(all,true)));}
    private JSONObject library(String id,String title,boolean movie,String path) throws Exception{return new JSONObject().put("id",id).put("name",title).put("movie",movie).put("path",path);}
    @Test public void defaultsHaveIndependentSources() throws Exception {JSONArray all=LibraryConfig.migrate(new JSONArray());assertEquals(2,all.length());JSONObject movies=LibraryConfig.defaultLibrary(all,true),shows=LibraryConfig.defaultLibrary(all,false);assertNotEquals(movies.getString("id"),shows.getString("id"));assertTrue(LibraryConfig.paths(movies).isEmpty());LibraryConfig.paths(movies,List.of("/movies"));assertTrue(LibraryConfig.paths(shows).isEmpty());}
    @Test public void oldNamedLibrariesBecomeDefaultsWithoutLosingIdsOrPaths() throws Exception {JSONArray all=LibraryConfig.migrate(new JSONArray().put(library("old-films","Filmek",true,"/usb/Film")).put(library("old-tv","TV műsorok",false,"/usb/TV")));assertEquals(2,all.length());assertEquals("old-films",LibraryConfig.defaultLibrary(all,true).getString("id"));assertEquals(List.of("/usb/Film"),LibraryConfig.paths(LibraryConfig.defaultLibrary(all,true)));assertEquals(List.of("/usb/TV"),LibraryConfig.paths(LibraryConfig.defaultLibrary(all,false)));}
    @Test public void otherCustomLibrariesAreNotSilentlyRenamedOrUsedAsDefaults() throws Exception {JSONArray all=LibraryConfig.migrate(new JSONArray().put(library("kids","Mesék",true,"/kids")));assertEquals(3,all.length());assertTrue(LibraryConfig.paths(LibraryConfig.defaultLibrary(all,true)).isEmpty());assertEquals("Mesék",LibraryConfig.find(all,"kids").getString("name"));}
    @Test public void migrationIsIdempotent() throws Exception {JSONArray once=LibraryConfig.migrate(new JSONArray().put(library("old","Filmek",true,"/movies")));JSONArray twice=LibraryConfig.migrate(once);assertEquals(once.toString(),twice.toString());}
    @Test public void pathsAreDeduplicatedAndRelativePathsAreIgnored() throws Exception {JSONObject l=new JSONObject().put("paths",new JSONArray(List.of("/movies/","/movies","relative","/other")));assertEquals(List.of("/movies","/other"),LibraryConfig.paths(l));}
    @Test public void editingDoesNotCreateAnotherLibrary() throws Exception {JSONArray all=LibraryConfig.migrate(new JSONArray().put(library("custom","Old",true,"/old")));JSONObject edit=new JSONObject(LibraryConfig.find(all,"custom").toString()).put("name","New");LibraryConfig.paths(edit,List.of("/new"));JSONArray result=LibraryConfig.replace(all,edit);assertEquals(3,result.length());assertEquals("New",LibraryConfig.find(result,"custom").getString("name"));assertEquals(List.of("/new"),LibraryConfig.paths(LibraryConfig.find(result,"custom")));}
    @Test public void deleteOnlyRemovesTheSelectedConfiguration() throws Exception {JSONArray all=LibraryConfig.migrate(new JSONArray().put(library("custom","Own",true,"/movies")));JSONArray result=LibraryConfig.remove(all,"custom");assertEquals(2,result.length());assertNotNull(LibraryConfig.defaultLibrary(result,true));assertNull(LibraryConfig.find(result,"custom"));}
    @Test public void metadataUsesLongestMatchingSourceRoot() throws Exception {JSONObject l=new JSONObject();LibraryConfig.paths(l,List.of("/media","/media/films"));assertEquals("/media/films",LibraryConfig.rootFor(l,"/media/films/film.mkv"));assertNull(LibraryConfig.rootFor(l,"/media2/film.mkv"));}
}
